mapper.sql:
WHERE 1 = 1


        AND NVL(post.PROJ_ID, replyPost.PROJ_ID) = #{projId}


        AND NVL(post.WS_ID, replyPost.WS_ID) = #{wsId}
        AND NVL(post.PROJ_ID, replyPost.PROJ_ID) IS NULL



    AND br.STATUS = #{status}


