       PROC_DT = SYSDATE,
       PROC_USER_ID = #{procUserId}
 WHERE REPORT_ID = #{reportId}

mapper.select:
SELECT COUNT(*) FROM BOARD_CHANNELS
WHERE DELETED_YN='N' AND UPPER(TRIM(CHANNEL_NAME))=UPPER(TRIM(#{channelName}))

    AND SCOPE_TYPE='PROJECT' AND PROJ_ID=#{projId}
    AND SCOPE_TYPE='GROUP' AND WS_ID=#{wsId} AND PROJ_ID IS NULL

AND CHANNEL_ID != #{excludeChannelId}

choose.when:
SELECT DISTINCT pm.USER_ID
  FROM PROJ_MEMBERS pm
 WHERE pm.PROJ_ID = #{projId, jdbcType=NUMERIC}
   AND pm.USER_ID != #{excludeUserId, jdbcType=NUMERIC}

choose.otherwise:
SELECT DISTINCT wm.USER_ID
  FROM WS_MEMBERS wm
 WHERE wm.WS_ID = #{wsId, jdbcType=NUMERIC}
   AND wm.USER_ID != #{excludeUserId, jdbcType=NUMERIC}
